# Builds every_node_2.graph.json: the nodes every_node.graph.json has no room for (a graph holds
# at most 400 nodes): the mode-building pieces (bot hints, barricades, loot, zone, drops, creatures
# with health/tier/pay), wired so it checks clean and so a sim run prints what each one did.
# The sim map needs: an ls_barricade named gate1, an ls_safe_zone named sz with an ls_zone_shrinker
# named shr, an entity named spot1 (creatures and the drop come there). Run from this folder.
import json

nodes, edges = [], []
row = [0]
def N(id, type, params=None, x=0):
    nodes.append({"id": id, "type": type, "pos": {"x": x * 260, "y": row[0] * 220}, "params": params or {}})
    return id
def W(a, ap, b, bp):
    edges.append({"id": f"w{len(edges)+1}", "from": {"node": a, "pin": ap}, "to": {"node": b, "pin": bp}})
def chain(*ids):
    for a, b in zip(ids, ids[1:]):
        W(a, "then", b, "exec")
def nl():
    row[0] += 1
def pr(id, text, x):
    return N(id, "debug.print", {"text": text, "chat": False}, x)

# a player spawns: tagged, friends with their tag, prefers the high layer
N("ps", "event.player_spawned")
N("tag", "bots.tag", {"tag": "sq1"}, 1); W("ps", "player", "tag", "player")
N("fr", "bots.friends", {"a": "tag", "a_tag": "sq1", "b": "tag", "b_tag": "sq1", "on": True}, 2)
N("ly", "bots.layer", {"who": "player", "tag": "", "layer": "high"}, 3); W("ps", "player", "ly", "player")
chain("ps", "tag", "fr", "ly")
nl()

# the round: phases, no buying, creatures as enemies, a goal and an offer at the barricade,
# its health set and mended, loot rolled, the zone pushed on, a creature with its own health/tier/pay,
# a supply drop called, then the fight
N("rs", "event.round_started")
N("ph", "bots.phase", {"phase": "loot"}, 1)
N("nb", "bots.no_buy", {"on": True}, 2)
N("ce", "bots.creature_enemies", {"on": True}, 3)
N("gate", "comp.find", {"name": "gate1"}, 3)
N("goal", "bots.goal", {"who": "ct", "tag": "", "kind": "defend", "prio": 40, "secs": 30, "radius": 128}, 4); W("gate", "out", "goal", "at")
N("off", "bots.offer", {"who": "all", "tag": "", "kind": "trap", "cost": 500, "order": 0}, 5); W("gate", "out", "off", "at")
N("gc", "bots.goal_clear", {"who": "ct", "tag": "", "kind": "defend"}, 6)
N("oc", "bots.offer_clear", {"who": "all", "tag": ""}, 7); W("gate", "out", "oc", "at")
chain("rs", "ph", "nb", "ce", "goal", "off", "gc", "oc")
nl()
N("bset", "comp.barricade_set_hp", {"hp": 50}, 0); W("gate", "out", "bset", "barricade")
N("bhp", "comp.barricade_hp", {}, 1); W("gate", "out", "bhp", "barricade")
N("p_bhp", "debug.print", {"text": "X2 barricade at:", "chat": False}, 1); W("bhp", "out", "p_bhp", "value")
N("brep", "comp.barricade_repair", {}, 2); W("gate", "out", "brep", "barricade")
N("bhp2", "comp.barricade_hp", {}, 3); W("gate", "out", "bhp2", "barricade")
N("p_bhp2", "debug.print", {"text": "X2 barricade mended:", "chat": False}, 3); W("bhp2", "out", "p_bhp2", "value")
N("loot", "comp.loot_roll", {"table": "default", "tier": 1}, 4)
N("p_loot", "debug.print", {"text": "X2 loot:", "chat": False}, 5); W("loot", "item", "p_loot", "value")
N("p_rolled", "debug.print", {"text": "X2 rolled:", "chat": False}, 6); W("loot", "rolled", "p_rolled", "value")
W("oc", "then", "bset", "exec")
chain("bset", "p_bhp", "brep", "p_bhp2", "loot", "p_loot", "p_rolled")
nl()
N("shr", "comp.find", {"name": "shr"}, 0)
N("skip", "comp.zone_skip", {}, 1); W("shr", "out", "skip", "zone")
N("zst", "comp.zone_stage", {}, 1); W("shr", "out", "zst", "zone")
N("p_zst", "debug.print", {"text": "X2 zone stage:", "chat": False}, 2); W("zst", "out", "p_zst", "value")
N("zn", "comp.zone_next", {}, 2); W("shr", "out", "zn", "zone")
N("fmt", "text.format", {"text": "X2 zone next: [0] s, radius [1], closing [2]"}, 3)
W("zn", "secs", "fmt", "a0"); W("zn", "radius", "fmt", "a1"); W("zn", "closing", "fmt", "a2")
N("p_zn", "debug.print", {"text": "", "chat": False}, 4); W("fmt", "out", "p_zn", "value")
W("p_rolled", "then", "skip", "exec")
chain("skip", "p_zst", "p_zn")
nl()
N("cs", "creature.spawn", {"kind": "zombie", "at": "spot1", "health": 300, "tier": "2", "pay": 150}, 0)
N("p_cs", "debug.print", {"text": "X2 creature:", "chat": False}, 1); W("cs", "out", "p_cs", "value")
N("chp", "creature.health", {}, 1); W("cs", "out", "chp", "in")
N("p_chp", "debug.print", {"text": "X2 creature health:", "chat": False}, 2); W("chp", "out", "p_chp", "value")
N("dz", "timer.delay", {"secs": 2}, 3)
N("zst2", "comp.zone_stage", {}, 3); W("shr", "out", "zst2", "zone")
N("p_zst2", "debug.print", {"text": "X2 zone stage 2 s later:", "chat": False}, 4); W("zst2", "out", "p_zst2", "value")
N("drop", "comp.drop_call", {"at": "spot1"}, 2)
N("ph2", "bots.phase", {"phase": "fight"}, 3)
W("p_zn", "then", "cs", "exec")
chain("cs", "p_cs", "p_chp", "drop", "ph2", "dz", "p_zst2")
nl()

# what the components say back
N("bd", "comp.on_barricade_damaged")
N("p_bd", "debug.print", {"text": "X2 barricade damaged, left:", "chat": False}, 1); W("bd", "hp", "p_bd", "value"); W("bd", "then", "p_bd", "exec")
N("br", "comp.on_barricade_repaired", {}, 2)
N("p_br", "debug.print", {"text": "X2 barricade repaired to:", "chat": False}, 3); W("br", "hp", "p_br", "value"); W("br", "then", "p_br", "exec")
N("dl", "comp.on_drop_landed", {}, 4)
N("p_dl", "debug.print", {"text": "X2 drop landed:", "chat": False}, 5); W("dl", "drop", "p_dl", "value"); W("dl", "then", "p_dl", "exec")
nl()
N("ck", "creature.on_killed")
N("p_ck", "debug.print", {"text": "X2 creature killed by:", "chat": False}, 1); W("ck", "killer", "p_ck", "value"); W("ck", "then", "p_ck", "exec")

# the Last Stand and Battle Royale pieces: on each spawn, a player's upgrades and items
nl()
N("ps2", "event.player_spawned")
N("mod", "up.mod", {"what": "speed", "mult": 1.1}, 1); W("ps2", "player", "mod", "player")
N("pg", "up.perk_give", {"perk": "tough"}, 2); W("ps2", "player", "pg", "player")
N("pb", "up.perk_buy", {"perk": "hands"}, 3); W("ps2", "player", "pb", "player")
N("p_pb", "debug.print", {"text": "X2 bought hands:", "chat": False}, 4); W("pb", "bought", "p_pb", "value")
N("ph_", "up.perk_has", {"perk": "tough"}, 4); W("ps2", "player", "ph_", "player")
N("p_ph", "debug.print", {"text": "X2 has tough:", "chat": False}, 5); W("ph_", "out", "p_ph", "value")
chain("ps2", "mod", "pg", "pb", "p_pb", "p_ph")
nl()
N("pc", "up.perk_count", {}, 0); W("ps2", "player", "pc", "player")
N("p_pc", "debug.print", {"text": "X2 perks:", "chat": False}, 1); W("pc", "out", "p_pc", "value")
N("mg", "up.mod_get", {"what": "speed"}, 1); W("ps2", "player", "mg", "player")
N("p_mg", "debug.print", {"text": "X2 speed times:", "chat": False}, 2); W("mg", "out", "p_mg", "value")
N("wl", "up.weapon_level", {}, 2); W("ps2", "player", "wl", "player")
N("p_wl", "debug.print", {"text": "X2 gun level:", "chat": False}, 3); W("wl", "out", "p_wl", "value")
N("bench", "up.bench", {}, 3); W("ps2", "player", "bench", "player")
N("box", "up.box", {}, 4); W("ps2", "player", "box", "player")
W("p_ph", "then", "p_pc", "exec")
chain("p_pc", "p_mg", "p_wl", "bench", "box")
nl()
N("kdn", "kd.down", {}, 0); W("ps2", "player", "kdn", "player")
N("kis", "kd.is", {}, 1); W("ps2", "player", "kis", "player")
N("p_kis", "debug.print", {"text": "X2 down:", "chat": False}, 1); W("kis", "out", "p_kis", "value")
N("kl", "kd.left", {}, 2); W("ps2", "player", "kl", "player")
N("p_kl", "debug.print", {"text": "X2 bleed left:", "chat": False}, 2); W("kl", "out", "p_kl", "value")
N("kup", "kd.revive", {}, 3); W("ps2", "player", "kup", "player")
N("hg", "br.heal_give", {"kind": "bandage", "n": 2}, 4); W("ps2", "player", "hg", "player")
N("hc", "br.heal_count", {}, 5); W("ps2", "player", "hc", "player")
N("p_hc", "debug.print", {"text": "X2 healing items:", "chat": False}, 5); W("hc", "out", "p_hc", "value")
N("arm", "br.armor", {"vest": "2", "helmet": "1"}, 6); W("ps2", "player", "arm", "player")
N("kills", "br.kills", {}, 6); W("ps2", "player", "kills", "player")
N("p_k", "debug.print", {"text": "X2 match kills:", "chat": False}, 7); W("kills", "out", "p_k", "value")
N("din", "br.drop_in", {}, 7); W("ps2", "player", "din", "player")
W("box", "then", "kdn", "exec")
chain("kdn", "p_kis", "p_kl", "kup", "hg", "p_hc", "arm", "p_k", "din")
nl()
# the round: the downed state on, a shop made, pickups and a crate, the match HUD, the squad lobby
N("rs3", "event.map_started")
N("kde", "kd.enable", {"on": True, "bleed": 30, "team": "0", "perks": True}, 1)
N("spot", "comp.find", {"name": "spot1"}, 1)
N("mkshop", "comp.create", {"kind": "ls_shop", "at": "spot1", "keys": "items=Ammo|300|ammo|refill;Armor|650|vesthelm|armor keeper=barney"}, 2)
N("sopen", "shop.open", {"open": True}, 3); W("mkshop", "out", "sopen", "shop")
N("sprice", "shop.price", {"item": "Ammo"}, 3); W("mkshop", "out", "sprice", "shop")
N("p_sp", "debug.print", {"text": "X2 shop ammo price:", "chat": False}, 4); W("sprice", "out", "p_sp", "value")
N("pick", "up.pickup", {"kind": "resupply", "life": 60, "colour": "gold"}, 5); W("spot", "out", "pick", "at")
N("crate", "br.crate", {"items": "bandage:2 ammo"}, 6); W("spot", "out", "crate", "at")
N("glow", "br.glow", {"tier": 4}, 7); W("crate", "out", "glow", "ent")
chain("rs3", "kde", "mkshop", "sopen", "p_sp", "pick", "crate", "glow")
nl()
N("hud", "br.hud", {"on": True}, 0)
N("hudt", "br.hud_text", {"text": "Loot up!"}, 1)
N("feed", "br.feed", {"text": "X2 feed line"}, 2)
N("ssz", "br.squad_size", {"size": 2}, 3)
N("lob", "br.lobby", {"secs": 5}, 4)
N("sal", "br.squads_alive", {}, 4)
N("p_sal", "debug.print", {"text": "X2 sides alive:", "chat": False}, 5); W("sal", "out", "p_sal", "value")
N("svar", "var.set", {"var": "shopv"}, 6); W("mkshop", "out", "svar", "value")
N("sget", "var.get", {"var": "shopv"}, 6)
N("smenu", "shop.menu", {}, 7); W("sget", "out", "smenu", "shop")
W("glow", "then", "hud", "exec")
chain("hud", "hudt", "feed", "ssz", "lob", "p_sal", "svar")
nl()
# the round table and turrets
nl()
N("wt", "wave.table", {"section": "", "team": "2", "creatures": True}, 0)
N("wsc", "wave.scale", {"count": 1.2, "hp": 1.1}, 1)
N("wcap", "wave.cap", {"n": 24}, 2)
N("wti", "wave.tiers", {"on": True}, 3)
N("tset", "turret.setup", {"price": 1500, "life": 120, "per": 1, "type": "turret", "bots": True}, 4)
N("winfo", "wave.info", {}, 4)
N("wfmt", "text.format", {"text": "X2 round: planned [0], made [1], health x[2], boss [3]"}, 5)
W("winfo", "planned", "wfmt", "a0"); W("winfo", "spawned", "wfmt", "a1"); W("winfo", "hp", "wfmt", "a2"); W("winfo", "boss", "wfmt", "a3")
N("p_winfo", "debug.print", {"text": "", "chat": False}, 6); W("wfmt", "out", "p_winfo", "value")
N("wpay", "wave.type_pay", {}, 6); W("winfo", "type", "wpay", "type")
N("wfmt2", "text.format", {"text": "X2 pack [0] type [1] pay [2]"}, 7); W("winfo", "pack", "wfmt2", "a0"); W("winfo", "type", "wfmt2", "a1"); W("wpay", "out", "wfmt2", "a2")
N("p_wpay", "debug.print", {"text": "", "chat": False}, 7); W("wfmt2", "out", "p_wpay", "value")
N("wok", "wave.creatures_ok", {}, 8)
N("p_wok", "debug.print", {"text": "X2 creatures working:", "chat": False}, 8); W("wok", "out", "p_wok", "value")
N("wtoff", "wave.table_off", {}, 9)
W("p_zst2", "then", "wt", "exec")
chain("wt", "wsc", "wcap", "wti", "tset", "p_winfo", "p_wpay", "p_wok", "wtoff")
nl()
N("tg", "turret.give", {"n": 1}, 0); W("ps2", "player", "tg", "player")
N("tk", "turret.kits", {}, 1); W("ps2", "player", "tk", "player")
N("p_tk", "debug.print", {"text": "X2 turret kits:", "chat": False}, 1); W("tk", "out", "p_tk", "value")
N("tp", "turret.place", {"pay": False}, 2); W("ps2", "player", "tp", "player")
N("p_tp", "debug.print", {"text": "X2 turret placed:", "chat": False}, 3); W("tp", "out", "p_tp", "value")
N("tc", "turret.count", {}, 3); W("ps2", "player", "tc", "player")
N("p_tc", "debug.print", {"text": "X2 turrets out:", "chat": False}, 4); W("tc", "out", "p_tc", "value")
W("din", "then", "tg", "exec")
chain("tg", "p_tk", "tp", "p_tp", "p_tc")

# what they say back
def ev(id, kind, text, pin, x):
    N(id, kind, {}, x)
    N("p_" + id, "debug.print", {"text": text, "chat": False}, x + 1)
    W(id, "then", "p_" + id, "exec")
    W(id, pin, "p_" + id, "value")
ev("e_perk", "up.on_perk", "X2 perk bought:", "perk", 0)
ev("e_up", "up.on_upgraded", "X2 gun upgraded to:", "level", 2)
ev("e_box", "up.on_box", "X2 box gave:", "weapon", 4)
ev("e_pick", "up.on_pickup", "X2 pickup taken:", "kind", 6)
nl()
ev("e_ch", "up.on_creature_hurt", "X2 creature hurt:", "damage", 0)
ev("e_kd", "kd.on_down", "X2 knocked down:", "player", 2)
ev("e_ku", "kd.on_up", "X2 got up:", "player", 4)
ev("e_bo", "kd.on_bled_out", "X2 bled out:", "player", 6)
nl()
ev("e_buy", "shop.on_buy", "X2 shop sold:", "item", 0)
ev("e_land", "br.on_landed", "X2 landed:", "player", 2)
ev("e_lob", "br.on_lobby_end", "X2 lobby ended, squads:", "squads", 4)
ev("e_tur", "turret.on_placed", "X2 turret placed by:", "owner", 6)
# a shop menu for a player as they land
W("p_e_land", "then", "smenu", "exec"); W("e_land", "player", "smenu", "player")

g = {"schema": "loner-strike/graph", "version": 3, "mode": {"id": "every_node_2", "name": "Every Node 2", "description": "Mode-building nodes"},
     "variables": [{"id": "shopv", "name": "Shop", "type": "entity", "scope": "mode"}], "nodes": nodes, "edges": edges, "comments": []}
json.dump(g, open("every_node_2.graph.json", "w"), indent=1)
print(len(nodes), "nodes", len(edges), "wires")
